steps.body:
A binary tree is built from nodes. Each node holds a value and two pointers, one to its left child and one to its right child. A missing child is `nullptr`.

```cpp
struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* root = new TreeNode{1, nullptr, nullptr};
root->left = new TreeNode{2, nullptr, nullptr};
```

Every node is its own heap allocation, just like a linked list node. `root` is just a pointer on the stack that leads to the rest. Code that walks a tree is recursive, with `nullptr` as the base case. The three depth-first orders differ only in when the node itself is visited:

- Preorder: the node, then the left subtree, then the right subtree.
- Inorder: the left subtree, the node, then the right subtree.
- Postorder: the left subtree, the right subtree, then the node.

Free a tree in postorder. Both children must be deleted before their parent, because reading `node->left` after `delete node` is a use after free. Production code would own nodes with `std::unique_ptr`, but raw pointers show the structure plainly.

example.code:
#include <iostream>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* newNode(int value) {
    return new TreeNode{value, nullptr, nullptr};
}

void preorder(const TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    std::cout << ' ' << node->value;
    preorder(node->left);
    preorder(node->right);
}

void inorder(const TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    inorder(node->left);
    std::cout << ' ' << node->value;
    inorder(node->right);
}

void postorder(const TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    postorder(node->left);
    postorder(node->right);
    std::cout << ' ' << node->value;
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    TreeNode* root = newNode(1);
    root->left = newNode(2);
    root->right = newNode(3);
    root->left->left = newNode(4);
    root->left->right = newNode(5);

    std::cout << "Preorder:";
    preorder(root);
    std::cout << '\n';
    std::cout << "Inorder:";
    inorder(root);
    std::cout << '\n';
    std::cout << "Postorder:";
    postorder(root);
    std::cout << '\n';

    freeTree(root);
    root = nullptr;
    return 0;
}

