steps.body:
Most tree questions share one recursive shape: give the answer for an empty tree, then combine the answers from both subtrees with the current node.

```cpp
int countNodes(const TreeNode* node) {
    if (node == nullptr) {
        return 0;   // an empty tree has no nodes
    }
    return 1 + countNodes(node->left) + countNodes(node->right);
}
```

- Height: 0 for `nullptr`, otherwise `1 + std::max(height(node->left), height(node->right))`. It counts the nodes on the longest path down from the root, so a lone node has height 1. Some books count edges instead, which gives a lone node height 0 and an empty tree -1.
- Sum: the node's value plus both subtree sums.
- Leaves: a node whose `left` and `right` are both `nullptr` counts as 1.
- Maximum: return a sentinel such as `INT_MIN` for an empty tree, so any real value beats it.

Always test `nullptr` first, because `node->left` on a null pointer is undefined behavior. Each function visits every node once, so it runs in O(n). The recursion is as deep as the tree is tall: each level adds one stack frame, and a tree shaped like a long chain needs one frame per node.

example.code:
#include <algorithm>
#include <iostream>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* newNode(int value) {
    return new TreeNode{value, nullptr, nullptr};
}

int height(const TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + std::max(height(node->left), height(node->right));
}

int countNodes(const TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }
    return 1 + countNodes(node->left) + countNodes(node->right);
}

int sumValues(const TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }
    return node->value + sumValues(node->left) + sumValues(node->right);
}

int countLeaves(const TreeNode* node) {
    if (node == nullptr) {
        return 0;
    }
    if (node->left == nullptr && node->right == nullptr) {
        return 1;
    }
    return countLeaves(node->left) + countLeaves(node->right);
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    TreeNode* root = newNode(4);
    root->left = newNode(9);
    root->right = newNode(2);
    root->left->left = newNode(7);
    root->left->right = newNode(1);
    root->right->right = newNode(6);
    root->right->right->left = newNode(3);

    std::cout << "Height: " << height(root) << '\n';
    std::cout << "Nodes: " << countNodes(root) << '\n';
    std::cout << "Sum: " << sumValues(root) << '\n';
    std::cout << "Leaves: " << countLeaves(root) << '\n';

    freeTree(root);
    root = nullptr;
    return 0;
}

