steps.body:
A binary search tree (BST) keeps one rule at every node: values in the left subtree are smaller and values in the right subtree are larger. Insert walks down that rule and returns the root of the subtree it was given.

```cpp
TreeNode* insert(TreeNode* node, int value) {
    if (node == nullptr) {
        return new TreeNode{value, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return node;   // an equal value is ignored
}
```

The caller writes `root = insert(root, x);`, which also handles the empty tree. A value already present matches neither branch, so the tree is returned unchanged.

Search follows the same path: left when the target is smaller, right when larger. It costs O(height), which is O(log n) when the tree is bushy. Inorder traversal of a BST prints the values sorted. The minimum is the leftmost node and the maximum the rightmost.

The catch: ascending input makes every new node a right child, so the tree becomes a chain with height n and search drops to O(n). `std::set` is a balanced BST (a red-black tree in libstdc++) that keeps height O(log n) automatically. Use it in real code, and write your own when you need the nodes themselves.

example.code:
#include <iostream>
#include <vector>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* insert(TreeNode* node, int value) {
    if (node == nullptr) {
        return new TreeNode{value, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return node;
}

bool contains(const TreeNode* node, int target) {
    while (node != nullptr) {
        if (target == node->value) {
            return true;
        }
        node = (target < node->value) ? node->left : node->right;
    }
    return false;
}

void inorder(const TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    inorder(node->left);
    std::cout << ' ' << node->value;
    inorder(node->right);
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    TreeNode* root = nullptr;
    const std::vector<int> values = {50, 30, 70, 20, 40, 60, 80, 40};
    for (int v : values) {
        root = insert(root, v);
    }

    std::cout << "Inorder:";
    inorder(root);
    std::cout << '\n';

    const std::vector<int> targets = {60, 65};
    for (int t : targets) {
        std::cout << t << ": " << (contains(root, t) ? "found" : "missing") << '\n';
    }
    const TreeNode* lowest = root;
    while (lowest->left != nullptr) {
        lowest = lowest->left;
    }
    const TreeNode* highest = root;
    while (highest->right != nullptr) {
        highest = highest->right;
    }
    std::cout << "Min: " << lowest->value << '\n';
    std::cout << "Max: " << highest->value << '\n';

    freeTree(root);
    root = nullptr;
    return 0;
}

