#include <cstddef>
#include <iostream>
#include <queue>
#include <vector>

struct TreeNode {
    int value;
    TreeNode* left;
    TreeNode* right;
};

TreeNode* insert(TreeNode* node, int value) {
    if (node == nullptr) {
        return new TreeNode{value, nullptr, nullptr};
    }
    if (value < node->value) {
        node->left = insert(node->left, value);
    } else if (value > node->value) {
        node->right = insert(node->right, value);
    }
    return node;
}

void printLevels(const TreeNode* root) {
    if (root == nullptr) {
        return;
    }
    std::queue<const TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        const std::size_t levelSize = q.size();
        for (std::size_t i = 0; i < levelSize; ++i) {
            const TreeNode* node = q.front();
            q.pop();
            if (i > 0) {
                std::cout << ' ';
            }
            std::cout << node->value;
            if (node->left != nullptr) {
                q.push(node->left);
            }
            if (node->right != nullptr) {
                q.push(node->right);
            }
        }
        std::cout << '\n';
    }
}

void freeTree(TreeNode* node) {
    if (node == nullptr) {
        return;
    }
    freeTree(node->left);
    freeTree(node->right);
    delete node;
}

int main() {
    TreeNode* root = nullptr;
    const std::vector<int> values = {50, 30, 70, 20, 40, 60, 80};
    for (int v : values) {
        root = insert(root, v);
    }

    printLevels(root);

    freeTree(root);
    root = nullptr;
    return 0;
